SourceCode.Declaration:
/// <summary>
/// PricingAttribute of table <c>InventTable</c> field ItemId.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(InventTable, ItemId))]
internal class GUPPricingAttributeInventTableItemId extends GUPPricingAttributeInventTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, ItemId);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    InventTable inventTable;
    EcoResProductTranslation ecoResProductTranslation;

    while select ItemId from inventTable
        outer join Name from ecoResProductTranslation
        group by inventTable.ItemId, ecoResProductTranslation.Name
        where inventTable.Product == ecoResProductTranslation.Product
            && ecoResProductTranslation.LanguageId == SystemParameters::getSystemLanguageId()
    {
        GUPPricingAttributeAllowedValuesObject valueObject = 
            new GUPPricingAttributeAllowedValuesObject(inventTable.ItemId, ecoResProductTranslation.Name);
        ret.add(valueObject);
    }
    return ret;
}
